def _sha256_file_exact_size(path: Path, expected_size: int, owner: str) -> bytes:
    if expected_size < 0:
        raise SystemExit(f"negative exact-hash bound for {owner}")
    digest = hashlib.sha256()
    remaining = expected_size
    with path.open("rb") as handle:
        while remaining:
            chunk = handle.read(min(1024 * 1024, remaining))
            if not chunk:
                raise SystemExit(f"{owner} was truncated while hashed: {path}")
            digest.update(chunk)
            remaining -= len(chunk)
        if handle.read(1) != b"":
            raise SystemExit(f"{owner} grew beyond its exact hash bound: {path}")
    return digest.digest()


def _raw_sha256(path: Path, expected_size: int) -> str:
    return _sha256_file_exact_size(path, expected_size, "raw SHA-256 input").hex()


def _reject_reparse(path: Path, owner: str) -> None:
    metadata = path.lstat()
    if path.is_symlink() or bool(
        getattr(metadata, "st_file_attributes", 0) & stat.FILE_ATTRIBUTE_REPARSE_POINT
    ):
        raise SystemExit(f"{owner} is a symlink or reparse point: {path}")


def _path_lexists(path: Path) -> bool:
    try:
        path.lstat()
    except FileNotFoundError:
        return False
    return True


def _reject_reparse_chain(path: Path, owner: str) -> None:
    absolute = path.absolute()
    for component in reversed((absolute, *absolute.parents)):
        if not _path_lexists(component):
            raise SystemExit(f"{owner} path is missing: {component}")
        _reject_reparse(component, owner)


def _reject_reparse_tree(
    root: Path, owner: str, *, maximum_entries: int,
) -> list[tuple[Path, bool]]:
    """Return a bounded typed tree surface and fail on enumeration errors."""

    _reject_reparse_chain(root, owner)
    if not root.is_dir() or maximum_entries < 1:
        raise SystemExit(f"{owner} is not a directory or has an invalid tree-entry bound: {root}")
    pending = [root]
    observed: list[tuple[Path, bool]] = []
    while pending:
        directory = pending.pop()
        try:
            iterator = os.scandir(directory)
        except OSError as exc:
            raise SystemExit(f"{owner} cannot be completely enumerated: {directory}: {exc}") from exc
        with iterator:
            try:
                for entry in iterator:
                    if len(observed) >= maximum_entries:
                        raise SystemExit(f"{owner} exceeds its {maximum_entries}-entry tree bound")
                    path = Path(entry.path)
                    try:
                        metadata = path.lstat()
                    except OSError as exc:
                        raise SystemExit(f"{owner} entry cannot be inspected: {path}: {exc}") from exc
                    if entry.is_symlink() or bool(
                        getattr(metadata, "st_file_attributes", 0) & stat.FILE_ATTRIBUTE_REPARSE_POINT
                    ):
                        raise SystemExit(f"{owner} contains a symlink or reparse point: {path}")
                    is_directory = stat.S_ISDIR(metadata.st_mode)
                    observed.append((path, is_directory))
                    if is_directory:
                        pending.append(path)
            except OSError as exc:
                raise SystemExit(f"{owner} cannot be completely enumerated: {directory}: {exc}") from exc
    return sorted(
        observed,
        key=lambda row: row[0].relative_to(root).as_posix().encode("utf-8"),
    )


def _inventory_rows_from_surface(
    root: Path,
    candidates: list[tuple[Path, bool]],
    *,
    owner: str,
    maximum_file_count: int,
    maximum_size_bytes: int,
    skip_pycache: bool,
    forbidden_suffixes: frozenset[str],
) -> list[tuple[str, int, bytes]]:
    """Hash one typed surface with exact bounds and stable metadata."""

    rows: list[tuple[str, int, bytes]] = []
    cumulative_size = 0
    for candidate, is_directory in candidates:
        relative = candidate.relative_to(root)
        before = candidate.lstat()
        if is_directory or (skip_pycache and "__pycache__" in relative.parts):
            continue
        if not candidate.is_file() or candidate.suffix.casefold() in forbidden_suffixes:
            raise SystemExit(f"{owner} contains a forbidden entry: {relative.as_posix()}")
        if len(rows) >= maximum_file_count:
            raise SystemExit(f"{owner} exceeds its exact file-count bound")
        cumulative_size += before.st_size
        if cumulative_size > maximum_size_bytes:
            raise SystemExit(f"{owner} exceeds its exact byte bound")
        raw_hash = _sha256_file_exact_size(candidate, before.st_size, owner)
        after = candidate.lstat()
        if (
            (before.st_mode, before.st_ino, before.st_size, before.st_mtime_ns, before.st_nlink)
            != (after.st_mode, after.st_ino, after.st_size, after.st_mtime_ns, after.st_nlink)
        ):
            raise SystemExit(f"{owner} entry changed while inventoried: {relative.as_posix()}")
        rows.append((relative.as_posix(), before.st_size, raw_hash))
    return rows


def _dependency_surface(site_root: Path) -> list[tuple[Path, bool]]:
    """Enumerate the complete allowlisted dependency projection for one pass."""

    result: list[tuple[Path, bool]] = []
    for root_name in RUNTIME_ROOTS:
        root = site_root / root_name
        _reject_reparse(root, f"successor runtime root {root_name}")
        if root_name.endswith(".py"):
            candidates = [(root, False)]
            stem = root_name.removesuffix(".py")
            collisions = [
                site_root / stem,
                site_root / (stem + ".pyc"),
                site_root / (stem + ".pyd"),
                site_root / (stem + ".pyw"),
            ]
        else:
            candidates = _reject_reparse_tree(
                root, f"successor runtime root {root_name}",
                maximum_entries=DEPENDENCY_ROOT_MAX_TREE_ENTRIES,
            )
            collisions = [
                site_root / (root_name + suffix)
                for suffix in (".py", ".pyc", ".pyd", ".pyw")
            ]
        if any(item.exists() or item.is_symlink() for item in collisions):
            raise SystemExit(f"successor runtime import collision: {root_name}")
        result.extend(candidates)
    return sorted(
        result,
        key=lambda row: row[0].relative_to(site_root).as_posix().encode("utf-8"),
    )


def _read_bounded_stable(path: Path, maximum_bytes: int, owner: str) -> bytes:
    _reject_reparse_chain(path, owner)
    before = path.lstat()
    if not path.is_file() or path.is_symlink() or before.st_size > maximum_bytes:
        raise SystemExit(f"{owner} is not a bounded regular file: {path}")
    with path.open("rb") as handle:
        raw = handle.read(maximum_bytes + 1)
    after = path.lstat()
    if (
        len(raw) > maximum_bytes
        or len(raw) != before.st_size
        or (before.st_mode, before.st_ino, before.st_size, before.st_mtime_ns)
        != (after.st_mode, after.st_ino, after.st_size, after.st_mtime_ns)
    ):
        raise SystemExit(f"{owner} changed or exceeded its bound while read: {path}")
    return raw


def _git_runtime_inventory() -> dict[str, Any]:
    """Hash the complete Git runtime closure with unambiguous binary rows."""

    root = GIT_RUNTIME_ROOT.absolute()
    candidates = _reject_reparse_tree(
        root, "frozen Git runtime", maximum_entries=GIT_RUNTIME_MAX_TREE_ENTRIES,
    )
    rows = _inventory_rows_from_surface(
        root, candidates, owner="frozen Git runtime",
        maximum_file_count=GIT_RUNTIME_FILE_COUNT,
        maximum_size_bytes=GIT_RUNTIME_SIZE_BYTES,
        skip_pycache=False, forbidden_suffixes=frozenset(),
    )
    final_candidates = _reject_reparse_tree(
        root, "frozen Git runtime final pass",
        maximum_entries=GIT_RUNTIME_MAX_TREE_ENTRIES,
    )
    if [(path.relative_to(root), kind) for path, kind in candidates] != [
        (path.relative_to(root), kind) for path, kind in final_candidates
    ]:
        raise SystemExit("frozen Git runtime surface changed while inventoried")
    final_rows = _inventory_rows_from_surface(
        root, final_candidates, owner="frozen Git runtime final pass",
        maximum_file_count=GIT_RUNTIME_FILE_COUNT,
        maximum_size_bytes=GIT_RUNTIME_SIZE_BYTES,
        skip_pycache=False, forbidden_suffixes=frozenset(),
    )
    if final_rows != rows:
        raise SystemExit("frozen Git runtime bytes changed between complete inventory passes")
    if not rows:
        raise SystemExit(f"frozen Git runtime inventory is empty: {root}")
    digest = hashlib.sha256(GIT_RUNTIME_INVENTORY_DOMAIN)
    for relative, size, raw_hash in sorted(rows, key=lambda row: row[0].encode("utf-8")):
        encoded = relative.encode("utf-8")
        digest.update(len(encoded).to_bytes(8, "big"))
        digest.update(encoded)
        digest.update(size.to_bytes(8, "big"))
        digest.update(raw_hash)
    value = {
        "root": str(root), "file_count": len(rows),
        "size_bytes": sum(row[1] for row in rows),
        "digest_domain": GIT_RUNTIME_INVENTORY_DOMAIN[:-1].decode("ascii"),
        "sha256": "sha256:" + digest.hexdigest(),
    }
    if (value["file_count"], value["size_bytes"], value["sha256"]) != (
        GIT_RUNTIME_FILE_COUNT, GIT_RUNTIME_SIZE_BYTES, "sha256:" + GIT_RUNTIME_SHA256,
    ):
        raise SystemExit("frozen Git runtime inventory mismatch")
    return value


def _raw_local_git_config_names(config_path: Path) -> list[str]:
    raw = _read_bounded_stable(config_path, BUILDER_MAX_INPUT_BYTES, "local Git config")
    if b"\0" in raw or b"\r" in raw:
        raise SystemExit("local Git config contains forbidden bytes")
    try:
        text = raw.decode("utf-8", "strict")
    except UnicodeDecodeError as exc:
        raise SystemExit("local Git config is not strict UTF-8") from exc
    section: str | None = None
    names: list[str] = []
    for number, source_line in enumerate(text.splitlines(), 1):
        line = source_line.strip()
        if not line or line.startswith(("#", ";")):
            continue
        section_match = re.fullmatch(r'\[([A-Za-z0-9.-]+)(?:\s+"([^"\\\r\n]+)")?\]', line)
        if section_match is not None:
            section = section_match.group(1).casefold()
            subsection = section_match.group(2)
            if subsection is not None:
                section += "." + subsection.casefold()
            continue
        if section is None:
            raise SystemExit(f"local Git config key precedes section at line {number}")
        key_match = re.fullmatch(r"([A-Za-z][A-Za-z0-9-]*)\s*=.*", line)
        if key_match is None:
            raise SystemExit(f"unsupported local Git config syntax at line {number}")
        names.append(section + "." + key_match.group(1).casefold())
    return names


def _validate_git_index_structure(index: Path) -> None:
    raw = _read_bounded_stable(index, BUILDER_MAX_INPUT_BYTES, "Git index")
    if len(raw) < 32 or raw[:4] != b"DIRC":
        raise SystemExit("Git index header is invalid")
    if int.from_bytes(raw[4:8], "big") != 2:
        raise SystemExit("Git index must use the exact self-contained v2 format")
    if hashlib.sha1(raw[:-20]).digest() != raw[-20:]:
        raise SystemExit("Git index checksum mismatch")
    entry_count = int.from_bytes(raw[8:12], "big")
    offset = 12
    payload_end = len(raw) - 20
    for ordinal in range(entry_count):
        if offset + 62 > payload_end:
            raise SystemExit(f"Git index entry {ordinal + 1} is truncated")
        flags = int.from_bytes(raw[offset + 60:offset + 62], "big")
        if flags & 0xF000:
            raise SystemExit(
                "Git index entry uses assume-valid, extended, or nonzero merge-stage flags"
            )
        name_end = raw.find(b"\0", offset + 62, payload_end)
        if name_end < 0:
            raise SystemExit(f"Git index entry {ordinal + 1} lacks a path terminator")
        name_length = name_end - (offset + 62)
        if (flags & 0x0FFF) != min(name_length, 0x0FFF):
            raise SystemExit(
                f"Git index entry {ordinal + 1} pathname-length flags are inconsistent"
            )
        entry_bytes = name_end + 1 - offset
        offset += (entry_bytes + 7) & ~7
        if offset > payload_end:
            raise SystemExit(f"Git index entry {ordinal + 1} padding is truncated")
    forbidden_extensions = {b"FSMN", b"UNTR", b"link"}
    while offset < payload_end:
        if offset + 8 > payload_end:
            raise SystemExit("Git index extension header is truncated")
        signature = raw[offset:offset + 4]
        size = int.from_bytes(raw[offset + 4:offset + 8], "big")
        offset += 8
        if offset + size > payload_end:
            raise SystemExit("Git index extension payload is truncated")
        if signature in forbidden_extensions:
            raise SystemExit(f"forbidden mutable/indirect Git index extension: {signature!r}")
        offset += size
    if offset != payload_end:
        raise SystemExit("Git index has trailing unparsed bytes")


def _preflight_git_administration(repository: Path) -> None:
    git_dir = repository / ".git"
    _reject_reparse_chain(repository, "repository root")
    _reject_reparse_chain(git_dir, "repository Git directory")
    if not git_dir.is_dir() or git_dir.is_symlink():
        raise SystemExit("ordinary sole-worktree .git directory required")
    for required in [
        git_dir / "config",
        git_dir / "HEAD",
        git_dir / "index",
        git_dir / "info" / "exclude",
    ]:
        _reject_reparse_chain(required, "Git administrative surface")
        if not required.is_file():
            raise SystemExit(f"Git administrative surface is not an ordinary file: {required}")
    _validate_git_index_structure(git_dir / "index")
    git_surface = _reject_reparse_tree(
        git_dir, "Git administrative tree",
        maximum_entries=REPOSITORY_MAX_TREE_ENTRIES,
    )
    top_level_locks = [
        git_dir / "index.lock", git_dir / "HEAD.lock", git_dir / "config.lock",
        git_dir / "packed-refs.lock",
    ]
    if any(_path_lexists(path) for path in top_level_locks):
        raise SystemExit("Git administrative lockfile is active or stale")
    if any(path.name.casefold().endswith(".lock") for path, _ in git_surface):
        raise SystemExit("Git administrative lockfile is active or stale")
    if any(
        path.parent == git_dir and path.name.casefold().startswith("sharedindex.")
        for path, _ in git_surface
    ):
        raise SystemExit("split-index shared state is forbidden")
    operation_markers = [
        git_dir / "MERGE_HEAD", git_dir / "CHERRY_PICK_HEAD", git_dir / "REVERT_HEAD",
        git_dir / "REBASE_HEAD", git_dir / "AUTO_MERGE", git_dir / "rebase-apply",
        git_dir / "rebase-merge", git_dir / "sequencer", git_dir / "BISECT_LOG",
        git_dir / "BISECT_START", git_dir / "BISECT_TERMS", git_dir / "BISECT_NAMES",
    ]
    if any(_path_lexists(path) for path in operation_markers):
        raise SystemExit(
            "an in-progress Git merge/rebase/cherry-pick/revert/bisect/sequencer operation is forbidden"
        )
    for forbidden in [
        git_dir / "commondir",
        git_dir / "config.worktree",
        git_dir / "shallow",
        git_dir / "worktrees",
        git_dir / "info" / "grafts",
        git_dir / "objects" / "info" / "alternates",
        git_dir / "objects" / "info" / "http-alternates",
    ]:
        if _path_lexists(forbidden):
            raise SystemExit(f"forbidden Git indirection: {forbidden}")
    names = _raw_local_git_config_names(git_dir / "config")
    dangerous_exact = {
        "core.fsmonitor",
        "core.untrackedcache",
        "core.attributesfile",
        "core.excludesfile",
        "core.hookspath",
        "core.sshcommand",
        "core.gitproxy",
        "core.alternaterefscommand",
        "core.worktree",
        "core.sparsecheckout",
        "core.splitindex",
        "uploadpack.packobjectshook",
        "extensions.worktreeconfig",
        "extensions.partialclone",
        "index.sparse",
    }
    if any(
        name in dangerous_exact
        or name.startswith((
            "include.", "includeif.", "filter.", "fsck.", "fetch.fsck.",
            "receive.fsck.", "http.", "credential.", "url.", "protocol.",
            "extensions.",
        ))
        or (
            name.startswith("remote.")
            and name.endswith((
                ".promisor", ".partialclonefilter", ".uploadpack", ".pushurl",
                ".proxy", ".receivepack",
            ))
        )
        or name.startswith("diff.")
        and name.endswith((".textconv", ".command", ".external"))
        or name.startswith("merge.")
        and name.endswith(".driver")
        or name.startswith("submodule.")
        and name.endswith(".update")
        for name in names
    ):
        raise SystemExit(
            "mutable, executable, sparse, included, or lazy-fetch local Git configuration rejected"
        )


def _verify_successor_runtime() -> Path:
    """Authenticate the interpreter and every importable third-party byte first."""

    if (
        sys.version_info[:3] != (3, 12, 13)
        or os.name != "nt"
        or sys.implementation.name != "cpython"
        or sys.implementation.cache_tag != "cpython-312"
    ):
        raise SystemExit("successor tooling requires exact CPython 3.12.13")
    observed_fixed = {name: os.environ.get(name) for name in LAUNCHER_FIXED_ENV}
    if observed_fixed != LAUNCHER_FIXED_ENV:
        raise SystemExit("successor tooling external launcher environment changed")
    if set(os.environ) != set(LAUNCHER_FIXED_ENV) | {"TEMP", "TMP"}:
        raise SystemExit("successor tooling inherited an unbound ambient environment variable")
    temp_text = os.environ.get("TEMP")
    if temp_text != os.environ.get("TMP") or not isinstance(temp_text, str) or not temp_text.startswith(LAUNCHER_TEMP_ROOT):
        raise SystemExit("successor tooling temporary directory is not the fresh launcher directory")
    for owner, path in [
        ("repository root", REPOSITORY), ("package directory", PACKAGE),
        ("frozen Python directory", FROZEN_PYTHON.parent),
    ]:
        _reject_reparse(path, owner)
    executable = Path(sys.executable).absolute()
    _reject_reparse(executable, "frozen Python executable")
    if executable != FROZEN_PYTHON or executable.stat().st_size != FROZEN_PYTHON_BYTES:
        raise SystemExit("successor tooling is not running under the frozen base interpreter")
    if _raw_sha256(executable, FROZEN_PYTHON_BYTES) != FROZEN_PYTHON_SHA256:
        raise SystemExit("frozen base interpreter hash mismatch")
    if (
        not FROZEN_PYTHON_DLL.is_file()
        or FROZEN_PYTHON_DLL.stat().st_size != FROZEN_PYTHON_DLL_BYTES
        or _raw_sha256(FROZEN_PYTHON_DLL, FROZEN_PYTHON_DLL_BYTES) != FROZEN_PYTHON_DLL_SHA256
    ):
        raise SystemExit("frozen CPython DLL identity mismatch")
    expected_sys_path = [
        FROZEN_PYTHON.parent / "python312.zip", FROZEN_PYTHON.parent / "DLLs",
        FROZEN_PYTHON.parent / "Lib", FROZEN_PYTHON.parent,
    ]
    if [os.path.normcase(os.path.abspath(value)) for value in sys.path] != [
        os.path.normcase(os.path.abspath(value)) for value in expected_sys_path
    ]:
        raise SystemExit("isolated standard-library path changed")
    if expected_sys_path[0].exists() or expected_sys_path[0].is_symlink():
        raise SystemExit("normally absent python312.zip became populated")
    cache_directory = Path(str(_CACHE_PREFIX_TEXT))
    _reject_reparse(cache_directory, "successor runtime pycache directory")
    if not cache_directory.is_dir() or any(cache_directory.iterdir()):
        raise SystemExit("successor runtime pycache directory is not fresh and empty")
    temp_directory = Path(temp_text)
    _reject_reparse(temp_directory, "successor runtime temporary directory")
    if not temp_directory.is_dir() or any(temp_directory.iterdir()):
        raise SystemExit("successor runtime temporary directory is not fresh and empty")

    base_candidates = _reject_reparse_tree(
        FROZEN_PYTHON.parent, "frozen base runtime",
        maximum_entries=BASE_RUNTIME_MAX_TREE_ENTRIES,
    )
    base_rows = _inventory_rows_from_surface(
        FROZEN_PYTHON.parent, base_candidates, owner="frozen base runtime",
        maximum_file_count=BASE_RUNTIME_FILE_COUNT,
        maximum_size_bytes=BASE_RUNTIME_SIZE_BYTES,
        skip_pycache=True, forbidden_suffixes=frozenset({".pyc"}),
    )
    final_base_candidates = _reject_reparse_tree(
        FROZEN_PYTHON.parent, "frozen base runtime final pass",
        maximum_entries=BASE_RUNTIME_MAX_TREE_ENTRIES,
    )
    if [(path.relative_to(FROZEN_PYTHON.parent), kind) for path, kind in base_candidates] != [
        (path.relative_to(FROZEN_PYTHON.parent), kind) for path, kind in final_base_candidates
    ]:
        raise SystemExit("frozen base runtime surface changed while inventoried")
    final_base_rows = _inventory_rows_from_surface(
        FROZEN_PYTHON.parent, final_base_candidates, owner="frozen base runtime final pass",
        maximum_file_count=BASE_RUNTIME_FILE_COUNT,
        maximum_size_bytes=BASE_RUNTIME_SIZE_BYTES,
        skip_pycache=True, forbidden_suffixes=frozenset({".pyc"}),
    )
    if final_base_rows != base_rows:
        raise SystemExit("frozen base runtime bytes changed between complete inventory passes")
    base_digest = hashlib.sha256(BASE_RUNTIME_INVENTORY_DOMAIN)
    for relative, size, file_hash in sorted(base_rows, key=lambda row: row[0].encode("utf-8")):
        encoded = relative.encode("utf-8")
        base_digest.update(len(encoded).to_bytes(8, "big")); base_digest.update(encoded)
        base_digest.update(size.to_bytes(8, "big")); base_digest.update(file_hash)
    if (len(base_rows), sum(row[1] for row in base_rows), base_digest.hexdigest()) != (
        BASE_RUNTIME_FILE_COUNT, BASE_RUNTIME_SIZE_BYTES, BASE_RUNTIME_SHA256,
    ):
        raise SystemExit("frozen base runtime inventory mismatch")

    site_root = REPOSITORY / ".venv" / "Lib" / "site-packages"
    if not site_root.is_dir() or site_root.is_symlink():
        raise SystemExit("frozen successor site-packages directory missing")
    for component in [REPOSITORY / ".venv", REPOSITORY / ".venv" / "Lib", site_root]:
        _reject_reparse(component, "successor runtime path")
    runtime_candidates = _dependency_surface(site_root)
    rows = _inventory_rows_from_surface(
        site_root, runtime_candidates, owner="successor runtime",
        maximum_file_count=RUNTIME_FILE_COUNT,
        maximum_size_bytes=RUNTIME_SIZE_BYTES,
        skip_pycache=True, forbidden_suffixes=frozenset({".pyc", ".pyo"}),
    )
    final_runtime_candidates = _dependency_surface(site_root)
    if [(path.relative_to(site_root), kind) for path, kind in runtime_candidates] != [
        (path.relative_to(site_root), kind) for path, kind in final_runtime_candidates
    ]:
        raise SystemExit("successor runtime surface changed between complete inventory passes")
    final_rows = _inventory_rows_from_surface(
        site_root, final_runtime_candidates, owner="successor runtime final pass",
        maximum_file_count=RUNTIME_FILE_COUNT,
        maximum_size_bytes=RUNTIME_SIZE_BYTES,
        skip_pycache=True, forbidden_suffixes=frozenset({".pyc", ".pyo"}),
    )
    if final_rows != rows:
        raise SystemExit("successor runtime bytes changed between complete inventory passes")
    digest = hashlib.sha256(RUNTIME_INVENTORY_DOMAIN)
    for relative, size, file_hash in sorted(rows, key=lambda row: row[0].encode("utf-8")):
        encoded = relative.encode("utf-8")
        digest.update(len(encoded).to_bytes(8, "big"))
        digest.update(encoded)
        digest.update(size.to_bytes(8, "big"))
        digest.update(file_hash)
    if (len(rows), sum(row[1] for row in rows), digest.hexdigest()) != (
        RUNTIME_FILE_COUNT,
        RUNTIME_SIZE_BYTES,
        RUNTIME_SHA256,
    ):
        raise SystemExit("successor third-party runtime inventory mismatch")
    return site_root


class _SuccessorRuntimeImportGuard:
    def __init__(self, site_packages: Path) -> None:
        self.site_packages = site_packages

    def find_spec(self, fullname: str, path: Any = None, target: Any = None) -> Any:
        del target
        top_level = fullname.partition(".")[0]
        if top_level in RUNTIME_TOP_LEVEL_IMPORTS:
            search = [str(self.site_packages)] if path is None else path
            spec = importlib.machinery.PathFinder.find_spec(fullname, search)
            if spec is None:
                raise ImportError(f"approved successor runtime import missing: {fullname}")
            candidates = []
            if spec.origin not in {None, "namespace"}:
                candidates.append(Path(spec.origin))
            if spec.submodule_search_locations is not None:
                candidates.extend(Path(item) for item in spec.submodule_search_locations)
            root = self.site_packages.resolve(strict=True)
            if not candidates:
                raise ImportError(f"approved successor runtime import has no origin: {fullname}")
            for candidate in candidates:
                try:
                    candidate.resolve(strict=True).relative_to(root)
                except (OSError, ValueError) as exc:
                    raise ImportError(f"successor runtime import escaped inventory: {fullname}") from exc
            return spec
        candidate = importlib.machinery.PathFinder.find_spec(fullname, [str(self.site_packages)])
        if candidate is not None:
            raise ImportError(f"unapproved successor site-package import blocked: {fullname}")
        return None


_SUCCESSOR_SITE_PACKAGES = _verify_successor_runtime()
sys.meta_path.insert(0, _SuccessorRuntimeImportGuard(_SUCCESSOR_SITE_PACKAGES))
sys.path.append(str(_SUCCESSOR_SITE_PACKAGES))
