def build_registry() -> dict[str, Any]:
    value: dict[str, Any] = {
        "format": "agent-assure-s1-successor-digest-domain-registry/1",
        "registry_digest_domain": "agent-assure:s1-successor-digest-domain-registry/v1",
        "entries": [
            {"id": item_id, "domain": domain, "projection": projection, "hash_algorithm": "sha256",
             "canonicalization": (
                 "length-prefixed-binary-rows/v1"
                 if item_id in BINARY_DOMAIN_FRAMINGS
                 else "RFC8785/JCS"
             ),
             "framing": (
                 BINARY_DOMAIN_FRAMINGS[item_id]
                 if item_id in BINARY_DOMAIN_FRAMINGS
                 else "UTF8(domain) || 0x00 || JCS(projection)"
             )}
            for item_id, domain, projection in DOMAINS
        ],
        "registry_digest": "",
    }
    projection = dict(value)
    projection.pop("registry_digest")
    value["registry_digest"] = domain_digest(value["registry_digest_domain"], projection)
    return value


