def build_contracts() -> dict[str, Any]:
    pre_nodes = [node_contract(node_id) for node_id in PRE_IDS]
    pre_edges = edges()
    full_nodes = pre_nodes + [node_contract(node_id) for node_id in POST_IDS]
    full_edges = pre_edges + [
        {"from": PRE_IDS[11], "to": POST_IDS[0]}, {"from": POST_IDS[0], "to": POST_IDS[1]},
        {"from": POST_IDS[1], "to": POST_IDS[2]}, {"from": POST_IDS[2], "to": POST_IDS[3]},
    ]
    pre_projection = {
        "nodes": pre_nodes, "edges": pre_edges, "terminal_node": PRE_IDS[-1],
        "max_combined_output_bytes": PRECLOSURE_OUTPUT_BUDGET_BYTES,
        "max_combined_semantic_output_bytes": PRECLOSURE_SEMANTIC_OUTPUT_BUDGET_BYTES,
    }
    full_projection = {
        "nodes": full_nodes, "edges": full_edges, "terminal_node": POST_IDS[-1],
        "max_combined_output_bytes": FULL_CEREMONY_OUTPUT_BUDGET_BYTES,
        "max_combined_semantic_output_bytes": FULL_CEREMONY_SEMANTIC_OUTPUT_BUDGET_BYTES,
    }
    tooling = []
    for role, relative in [
        ("runtime_launcher", "tools/successor_v3_launcher.ps1"),
        ("package_builder", "tools/build_design_package.py"),
        ("validator_importer", "tools/successor_v3_tool.py"),
    ]:
        descriptor = raw_descriptor(PACKAGE / relative)
        runtime = (
            "exact_Windows_PowerShell_5.1_launcher_authenticating_base_runtime"
            if role == "runtime_launcher"
            else "exact_frozen_CPython_3.12.13_with_authenticated_dependencies;source_syntax_CPython_3.11"
        )
        descriptor.update({"role": role, "runtime": runtime, "private_key_access": False})
        tooling.append(descriptor)
    value: dict[str, Any] = {
        "format": "agent-assure-s1-successor-check-contracts/2", "digest_domain": "agent-assure:s1-successor-check-contract-set/v2",
        "package_id": PACKAGE_ID, "tooling": tooling, "hosted_ci": HOSTED_CI_CONTRACT,
        "preclosure_graph": {"digest_domain": "agent-assure:s1-successor-preclosure-check-graph/v2", **pre_projection,
            "graph_digest": domain_digest("agent-assure:s1-successor-preclosure-check-graph/v2", pre_projection)},
        "full_ceremony_graph": {"digest_domain": "agent-assure:s1-successor-full-ceremony-check-graph/v2", **full_projection,
            "graph_digest": domain_digest("agent-assure:s1-successor-full-ceremony-check-graph/v2", full_projection)},
        "check_contracts_digest": "",
    }
    projection = dict(value)
    projection.pop("check_contracts_digest")
    value["check_contracts_digest"] = domain_digest(value["digest_domain"], projection)
    return value


